begin;
create table public.local_rank_keywords(id uuid primary key default gen_random_uuid(),business_id uuid not null references public.businesses(id) on delete cascade,search_query text not null,enabled boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create unique index local_rank_keywords_business_query_unique on public.local_rank_keywords(business_id,lower(search_query));
create table public.local_rank_scans(id uuid primary key default gen_random_uuid(),business_id uuid not null references public.businesses(id) on delete cascade,keyword_id uuid not null references public.local_rank_keywords(id) on delete cascade,provider text not null,status text not null check(status in('queued','running','completed','partial_failure','provider_unavailable','usage_limited','failed')),started_at timestamptz,completed_at timestamptz,grid_config jsonb not null default '{}'::jsonb,average_position numeric,top_3_percentage numeric,top_10_percentage numeric,created_at timestamptz not null default now());
create table public.local_rank_results(id uuid primary key default gen_random_uuid(),scan_id uuid not null references public.local_rank_scans(id) on delete cascade,latitude numeric not null,longitude numeric not null,rank integer,found boolean not null default false,competitors jsonb not null default '[]'::jsonb,raw_provider_reference text,created_at timestamptz not null default now());
create table public.local_rank_scan_schedules(business_id uuid primary key references public.businesses(id) on delete cascade,cadence text not null default 'monthly' check(cadence in('weekly','monthly')),enabled boolean not null default true,next_scan_at timestamptz,updated_at timestamptz not null default now());
create index local_rank_scans_business_keyword_idx on public.local_rank_scans(business_id,keyword_id,created_at desc);create index local_rank_results_scan_idx on public.local_rank_results(scan_id);
alter table public.local_rank_keywords enable row level security;alter table public.local_rank_scans enable row level security;alter table public.local_rank_results enable row level security;alter table public.local_rank_scan_schedules enable row level security;
create policy "members read local rank keywords" on public.local_rank_keywords for select to authenticated using(public.is_business_member(business_id));create policy "managers manage local rank keywords" on public.local_rank_keywords for all to authenticated using(public.has_business_role(business_id,array['owner','admin'])) with check(public.has_business_role(business_id,array['owner','admin']));
create policy "members read local rank scans" on public.local_rank_scans for select to authenticated using(public.is_business_member(business_id));create policy "members read local rank results" on public.local_rank_results for select to authenticated using(exists(select 1 from public.local_rank_scans s where s.id=scan_id and public.is_business_member(s.business_id)));create policy "members read local rank schedules" on public.local_rank_scan_schedules for select to authenticated using(public.is_business_member(business_id));
notify pgrst,'reload schema';commit;
